<?php use Addons\Grh\GrhService as S; require __DIR__ . '/_h.php'; $dec = can('grh.conges'); ?>
<?php if (can('grh.presences') && $actifs): ?><div class="card mb-3"><div class="card-header"><i class="bi bi-calendar-plus"></i> <?= e(t('Nouvelle demande de congé')) ?></div><div class="card-body"><form method="post" action="<?= e(url('/grh/conges')) ?>" class="row g-2"><?= csrf_field() ?>
  <?= grh_select('employe_id', 'Employé', grh_opts($actifs, fn ($r) => $r['last_name'] . ' ' . $r['first_name'] . ' (' . $r['matricule'] . ')', 'Choisir…'), '', 'required', 'col-md-3', false) ?><?= grh_select('kind', 'Type de congé', S::LEAVE_KINDS, 'annuel', '', 'col-md-2') ?>
  <?= grh_field('start_date', 'Du', '', 'date', 'required', 'col-md-2') ?><?= grh_field('end_date', 'Au (inclus)', '', 'date', 'required', 'col-md-2') ?><?= grh_field('reason', 'Motif', '', 'text', 'maxlength="250"', 'col-md-2') ?><div class="col-md-1 d-flex align-items-end"><button class="btn btn-sm btn-primary w-100"><?= e(t('Demander')) ?></button></div></form>
  <p class="small text-secondary mb-0 mt-2"><?= e(t('Les jours sont comptés en jours ouvrés (samedi et dimanche exclus). Les jours fériés ne sont pas déduits automatiquement.')) ?></p></div></div><?php endif; ?>
<div class="mb-2 d-flex flex-wrap gap-1"><a class="btn btn-sm <?= $status === '' ? 'btn-dark' : 'btn-outline-dark' ?>" href="<?= e(url('/grh/conges')) ?>"><?= e(t('Tous')) ?></a><?php foreach (S::LEAVE_STATUS as $k => $l): ?><a class="btn btn-sm <?= $status === $k ? 'btn-dark' : 'btn-outline-dark' ?>" href="<?= e(url('/grh/conges', ['status' => $k])) ?>"><?= e(t($l)) ?></a><?php endforeach; ?></div>
<div class="card"><div class="table-responsive"><table class="table table-sm align-middle mb-0 small"><thead><tr><th><?= e(t('Employé')) ?></th><th><?= e(t('Congé')) ?></th><th><?= e(t('Période')) ?></th><th class="num"><?= e(t('Jours')) ?></th><th><?= e(t('État')) ?></th><th></th></tr></thead><tbody>
<?php foreach ($p['rows'] as $g): $id = (int) $g['id']; ?><tr><td><a href="<?= e(url('/grh/employes/' . $g['employe_id'])) ?>"><?= e($g['last_name'] . ' ' . $g['first_name']) ?></a><div class="text-secondary"><?= e($g['matricule']) ?></div></td><td><?= e(t(S::LEAVE_KINDS[$g['kind']])) ?><div class="text-secondary"><?= e($g['reason']) ?></div></td>
  <td class="text-nowrap"><?= e(fdate($g['start_date'], false)) ?> → <?= e(fdate($g['end_date'], false)) ?></td><td class="num fw-semibold"><?= e(qty($g['days'])) ?><?= $g['solde'] !== null ? '<div class="fw-normal ' . ((float) $g['days'] > $g['solde'] ? 'text-danger' : 'text-secondary') . '">' . e(t('solde')) . ' ' . e(qty($g['solde'])) . '</div>' : '' ?></td>
  <td><?= grh_badge(S::LEAVE_STATUS[$g['status']], S::LEAVE_COLORS[$g['status']]) ?><?= $g['decider'] ? '<div class="text-secondary">' . e($g['decider']) . '</div>' : '' ?><?= $g['decision_note'] ? '<div>' . e($g['decision_note']) . '</div>' : '' ?></td>
  <td class="text-end text-nowrap"><?php if ($dec && $g['status'] === 'demande'): ?><form method="post" action="<?= e(url("/grh/conges/$id/decision")) ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="decision" value="approuver"><button class="btn btn-sm btn-success"><i class="bi bi-check-lg"></i> <?= e(t('Approuver')) ?></button></form>
    <button type="button" class="btn btn-sm btn-outline-danger" data-bs-toggle="collapse" data-bs-target="#ref<?= $id ?>"><?= e(t('Refuser')) ?></button><?php endif; ?>
    <?php if ($dec && $g['status'] === 'approuve' && $g['end_date'] >= date('Y-m-d')): ?><form method="post" action="<?= e(url("/grh/conges/$id/annuler")) ?>" class="d-inline" data-confirm="<?= e(t('Annuler ce congé approuvé ?')) ?>"><?= csrf_field() ?><input type="hidden" name="note" value="Annulé par les RH"><button class="btn btn-sm btn-outline-secondary"><?= e(t('Annuler')) ?></button></form><?php endif; ?></td></tr>
  <?php if ($dec && $g['status'] === 'demande'): ?><tr class="collapse" id="ref<?= $id ?>"><td colspan="6"><form method="post" action="<?= e(url("/grh/conges/$id/decision")) ?>" class="d-flex gap-2"><?= csrf_field() ?><input type="hidden" name="decision" value="refuser"><input name="note" class="form-control form-control-sm" required minlength="3" maxlength="255" placeholder="<?= e(t('Motif du refus (obligatoire)')) ?>"><button class="btn btn-sm btn-danger text-nowrap"><?= e(t('Refuser le congé')) ?></button></form></td></tr><?php endif; ?>
<?php endforeach; ?>
<?php if (!$p['rows']): ?><tr><td colspan="6" class="text-center text-secondary py-4"><?= e(t('Aucun congé.')) ?></td></tr><?php endif; ?></tbody></table></div></div>
